// GROUPES : un appel Gemini traite un groupe de chunks (8 par défaut, réglable avec params.groupe) ; chaque chunk garde son propre enrichissement
const items = $input.all();
const TAILLE_GROUPE = Number(items[0] && items[0].json.params && items[0].json.params.groupe) || 8;
const groupes = [];
for (let i = 0; i < items.length; i += TAILLE_GROUPE) {
  const lot = items.slice(i, i + TAILLE_GROUPE);
  const d = lot[0].json;
  const extraits = lot.map(x => '=== Extrait n° ' + x.json.ordre + ' ===\n' + x.json.texte).join('\n\n');
  groupes.push({ json: { debut: i, nombre: lot.length, prompt: 'Document : ' + d.titre + '\nDescription : ' + d.description + '\n\nVoici ' + lot.length + ' extraits de ce document. Produis un enrichissement pour CHACUN, dans le même ordre.\n\n' + extraits } });
}
return groupes;

// ASSEMBLAGE : redistribue les enrichissements des groupes sur chaque chunk ; produit un item par chunk, avec le texte à vectoriser
const sources = $('When Executed by Another Workflow').all();
const groupes = $('Préparer les groupes').all();
const sorties = $input.all();
if (sorties.length !== groupes.length) throw new Error('Enrichissement incomplet : ' + sorties.length + ' réponses pour ' + groupes.length + ' groupes');

const enrichis = [];
sorties.forEach((s, g) => {
  let out = s.json.output ?? s.json.text ?? s.json;
  if (typeof out === 'string') out = JSON.parse(out);
  const liste = out && out.enrichissements;
  const { debut, nombre } = groupes[g].json;
  if (!Array.isArray(liste) || liste.length !== nombre) throw new Error('Groupe ' + (g + 1) + ' : ' + (Array.isArray(liste) ? liste.length : 0) + ' enrichissements reçus pour ' + nombre + ' extraits');
  const ordres = sources.slice(debut, debut + nombre).map(x => x.json.ordre);
  const parNumero = new Map(liste.map(e => [Number(e.n), e]));
  // on s'appuie sur le numéro d'extrait renvoyé quand il est cohérent, sinon sur l'ordre
  enrichis.push(...(ordres.every(o => parNumero.has(o)) ? ordres.map(o => parNumero.get(o)) : liste));
});

return enrichis.map((enr, i) => {
  const src = sources[i].json;
  if (!enr || !enr.resume || !enr.contexte || !Array.isArray(enr.mots_cles) || !Array.isArray(enr.questions) || !Array.isArray(enr.entites) || !Array.isArray(enr.relations)) {
    throw new Error('Enrichissement invalide pour le chunk n°' + src.ordre);
  }
  const entites = enr.entites.map(x => x.nom + ' (' + x.type + ')').join(', ');
  const relations = enr.relations.map(r => r.sujet + ' — ' + r.relation + ' → ' + r.objet).join(' | ');
  const texte_embedding = [
    'Document : ' + src.titre,
    'Contexte : ' + enr.contexte,
    '',
    src.texte,
    '',
    'Résumé : ' + enr.resume,
    'Mots-clés : ' + enr.mots_cles.join(', '),
    'Questions types : ' + enr.questions.join(' | '),
    'Entités : ' + entites,
    'Relations : ' + relations
  ].join('\n');
  return { json: { collection: src.collection, titre: src.titre, description: src.description, source: src.source, format: src.format, params: src.params, ordre: src.ordre, texte: src.texte, contexte: enr.contexte, resume: enr.resume, questions: enr.questions, mots_cles: enr.mots_cles, entites: enr.entites, relations: enr.relations, texte_embedding } };
});
